    "diagnosisRules": {
        "validation_failed": {
            "title": "译文未通过校验",
            "suggestion": "查看失败段落的校验码及关联请求；请求成功不代表译文有效。"
        },
        "provider_request_failed": {
            "title": "模型请求失败",
            "suggestion": "结合状态码、服务商错误码和重试链检查服务配置与可用性。"
        },
        "provider_rate_limited": {
            "title": "模型请求受到限流",
            "suggestion": "检查对应请求的状态码及服务商额度；429 本身不能区分频率与额度限制。"
        },
        "interrupted_requests": {
            "title": "存在未确认完成的请求",
            "suggestion": "检查取消、进程退出或服务重启记录；未确认的请求不计为已成功或已失败。"
        },
        "evidence_incomplete": {
            "title": "证据链不完整",
            "suggestion": "部分历史、写入或容量证据缺失；不要据此推断没有发生请求。"
        },
        "cache_reused": {
            "title": "部分译文来自缓存或检查点",
            "suggestion": "这些段落没有新的模型请求；检查原始执行记录可了解此前调用。"
        },
        "paragraph_unresolved": {
            "title": "任务仍有未完成段落",
            "suggestion": "查看失败段落及其关联的批量请求、单段回退和校验结果。"
        },
        "evidence_unavailable": {
            "title": "当前任务没有可用的请求证据",
            "suggestion": "旧版本不会补造历史请求；可结合现有错误码判断，后续执行会产生关联证据。"
        }
    }
